--
-- Name: decrypt_sensitive(bytea, text); Type: FUNCTION; Schema: public; Owner: genba_user
--

CREATE FUNCTION public.decrypt_sensitive(ciphertext bytea, key text) RETURNS text
    LANGUAGE plpgsql STRICT
    AS $$
        BEGIN
            RETURN pgp_sym_decrypt(ciphertext, key, 'cipher-algo=aes256');
        EXCEPTION
            WHEN OTHERS THEN
                RAISE EXCEPTION '復号化に失敗しました。暗号キーが正しくない可能性があります。';
        END;
        $$;


ALTER FUNCTION public.decrypt_sensitive(ciphertext bytea, key text) OWNER TO genba_user;

--
-- Name: encrypt_sensitive(text, text); Type: FUNCTION; Schema: public; Owner: genba_user
--

CREATE FUNCTION public.encrypt_sensitive(plaintext text, key text) RETURNS bytea
    LANGUAGE plpgsql STRICT
    AS $$
        BEGIN
            RETURN pgp_sym_encrypt(plaintext, key, 'cipher-algo=aes256');
        END;
        $$;


ALTER FUNCTION public.encrypt_sensitive(plaintext text, key text) OWNER TO genba_user;

