--
-- Name: contracts; Type: TABLE; Schema: public; Owner: genba_user
--

CREATE TABLE public.contracts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    internal_code character varying(50) NOT NULL,
    external_code character varying(50),
    contract_type character varying(20) NOT NULL,
    service_type character varying(50) NOT NULL,
    service_area character varying(100),
    cleaning_type character varying(100),
    work_description text,
    amount numeric(12,2) NOT NULL,
    hourly_rate numeric(10,2),
    tax_type character varying(10) DEFAULT 'EXCLUSIVE'::character varying NOT NULL,
    start_date date NOT NULL,
    end_date date,
    auto_renew boolean DEFAULT false NOT NULL,
    invoice_required boolean DEFAULT true NOT NULL,
    status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    genba_id uuid NOT NULL,
    customer_id uuid,
    partner_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    contract_name character varying(200),
    service_category character varying(20) DEFAULT 'OTHER'::character varying NOT NULL,
    weekly_frequency smallint,
    work_days character varying(50),
    work_start_time time without time zone,
    work_end_time time without time zone,
    work_duration_hours numeric(4,2),
    contract_pdf_url character varying(500),
    work_type character varying(50),
    sub_service_type character varying(50),
    work_execution_date date,
    work_content_summary text,
    CONSTRAINT chk_contract_party CHECK (((((contract_type)::text = 'RECEIVING'::text) AND (customer_id IS NOT NULL)) OR (((contract_type)::text = 'ORDERING'::text) AND (partner_id IS NOT NULL)))),
    CONSTRAINT chk_contracts_contract_type CHECK (((contract_type)::text = ANY ((ARRAY['RECEIVING'::character varying, 'ORDERING'::character varying])::text[]))),
    CONSTRAINT chk_contracts_service_category CHECK (((service_category)::text = ANY ((ARRAY['DAILY'::character varying, 'PERIODIC'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT chk_contracts_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PENDING_APPROVAL'::character varying, 'ACTIVE'::character varying, 'EXPIRED'::character varying, 'CANCELLED'::character varying])::text[])))
);

