    special_notes text,
    management_start_date date,
    terminated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    genba_type character varying(30),
    genba_type_other character varying(100),
    floor_above_ground smallint,
    floor_basement smallint,
    CONSTRAINT chk_genba_genba_type CHECK (((genba_type IS NULL) OR ((genba_type)::text = ANY ((ARRAY['MANSION'::character varying, 'OFFICE_BUILDING'::character varying, 'LOGISTICS_CENTER'::character varying, 'OTHER'::character varying])::text[])))),
    CONSTRAINT chk_genba_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'TERMINATED'::character varying])::text[]))),
    CONSTRAINT chk_genba_type_other_required CHECK ((((genba_type)::text <> 'OTHER'::text) OR (genba_type_other IS NOT NULL)))
